/** Root of a capacity hierarchy: a leaf carries a value, a group carries children, never both. */
export type Data = { name: string; value?: number; children?: Data[] };

type Cell = d3.HierarchyRectangularNode<Data>;

const MARGIN = { top: 12, right: 12, bottom: 12, left: 12 };
const PADDING_OUTER = 3;
const PADDING_TOP = 19;
const PADDING_INNER = 1;
const FONT_SIZE = 10;
/** Mean advance width of 10px sans-serif, used to drop labels that would overflow their rect. */
const CHAR_WIDTH = 5.6;
const LABEL_INSET = 4;
/** A leaf shorter than this cannot hold both baselines (1.1em and 2.3em) without spilling. */
const MIN_LEAF_HEIGHT = 27;
const MIN_LABEL_HEIGHT = 16;

const format = d3.format(',d');

/**
 * Lu and Fogarty's cascade: pull each node's right and bottom edges in by two padding units
 * per level of descendants sharing that edge, so every child overhangs its parent by exactly
 * the padding and its shadow falls outside the parent instead of onto it.
 */
function cascade(root: Cell, offset: number): Cell {
  const xSteps = new Map<Cell, number>();
  const ySteps = new Map<Cell, number>();

  root.eachAfter((node) => {
    const children = node.children ?? [];
    // d3.max skips the NaN emitted for children that do not share the edge; no sharing child
    // at all leaves it undefined, and the -1 then cancels the +1 into no cascade.
    const x = d3.max(children, (c) => (c.x1 === node.x1 - offset ? (xSteps.get(c) ?? 0) : NaN));
    const y = d3.max(children, (c) => (c.y1 === node.y1 - offset ? (ySteps.get(c) ?? 0) : NaN));
    xSteps.set(node, children.length === 0 ? 0 : 1 + (x ?? -1));
    ySteps.set(node, children.length === 0 ? 0 : 1 + (y ?? -1));
  });

  root.eachBefore((node) => {
    node.x1 -= 2 * offset * (xSteps.get(node) ?? 0);
    node.y1 -= 2 * offset * (ySteps.get(node) ?? 0);
  });

  return root;
}

function pathOf(node: Cell): string {
  return node
    .ancestors()
    .map((a) => a.data.name)
    .reverse()
    .join('/');
}

/** Pale upper levels need dark ink, dark lower levels need light ink. */
function inkFor(fill: string): string {
  return d3.lab(fill).l > 62 ? '#1c1408' : '#f4efe8';
}

export default function CascadedTreemap({
  data = storageEstate,
  width
}: {
  data?: Data;
  width: number;
}) {
  const height = Math.round(width * 1.15);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;
  const shadowId = `cascaded-treemap-shadow-${useId().replace(/:/g, '')}`;

  const root = useMemo(
    () =>
      cascade(
        d3
          .treemap<Data>()
          .size([innerWidth, innerHeight])
          .paddingOuter(PADDING_OUTER)
          .paddingTop(PADDING_TOP)
          .paddingInner(PADDING_INNER)
          .round(true)(
          d3
            .hierarchy(data)
            .sum((d) => d.value ?? 0)
            .sort((a, b) => (b.value ?? 0) - (a.value ?? 0))
        ),
        PADDING_OUTER
      ),
    [data, innerWidth, innerHeight]
  );

  // Depth is the cascade level, so it drives both the paint order and the ramp.
  const levels = useMemo(
    () => d3.groups(root.descendants(), (d) => d.depth).sort(([a], [b]) => a - b),
    [root]
  );

  const color = useMemo(
    () =>
      d3
        .scaleSequential<string>((t) => d3.interpolateYlOrBr(0.22 + t * 0.62))
        .domain([root.height, 0]),
    [root.height]
  );

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Cascaded treemap of provisioned storage capacity, each nesting level offset and shadowed so depth reads as physical stacking"
    >
      <defs>
        <filter id={shadowId}>
          <feDropShadow dx={0} dy={2} stdDeviation={3} floodOpacity={0.55} />
        </filter>
      </defs>
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`} fontSize={FONT_SIZE}>
        {levels.map(([depth, nodes]) => (
          // One filter per level, not per node: a level casts a single shadow onto the
          // level behind it rather than each sibling shadowing its own neighbours.
          <g key={depth} filter={`url(#${shadowId})`}>
            {nodes.map((d) => {
              const cellWidth = Math.max(0, d.x1 - d.x0);
              const cellHeight = Math.max(0, d.y1 - d.y0);
              const value = format(d.value ?? 0);
              const room = cellWidth - LABEL_INSET * 2;
              const fill = color(d.depth);
              const ink = inkFor(fill);
              const isLeaf = !d.children;
              const fitsName =
                cellHeight >= MIN_LABEL_HEIGHT && d.data.name.length * CHAR_WIDTH <= room;
              const fitsValue = isLeaf
                ? cellHeight >= MIN_LEAF_HEIGHT && value.length * CHAR_WIDTH <= room
                : (d.data.name.length + value.length + 1) * CHAR_WIDTH <= room;

              return (
                <g key={pathOf(d)} transform={`translate(${d.x0},${d.y0})`}>
                  <title>{`${pathOf(d)}\n${value} TiB`}</title>
                  <rect width={cellWidth} height={cellHeight} fill={fill} />
                  {fitsName && (
                    <text x={LABEL_INSET} fill={ink}>
                      {isLeaf ? (
                        <>
                          <tspan x={LABEL_INSET} y="1.1em">
                            {d.data.name}
                          </tspan>
                          {fitsValue && (
                            <tspan x={LABEL_INSET} y="2.3em" fillOpacity={0.7}>
                              {value}
                            </tspan>
                          )}
                        </>
                      ) : (
                        <tspan y={13}>
                          {d.data.name}
                          {fitsValue && <tspan fillOpacity={0.7}>{` ${value}`}</tspan>}
                        </tspan>
                      )}
                    </text>
                  )}
                </g>
              );
            })}
          </g>
        ))}
      </g>
    </svg>
  );
}
